uint8_t bitmap[1] = {0x35};          // 00110101
int32_t values[6] = {7, 0, 3, 0, 5, 9}; // slots 1, 3: any value
int64_t sum = 0;
for (int j = 0; j < 6; j++) {
  bool valid = bitmap[j / 8] & (1 << (j % 8));
  if (valid) sum += values[j];
}

void map_plus_double_col_double_col(int n, double *__restrict__ res,
    double *__restrict__ col1, double *__restrict__ col2,
    int *__restrict__ sel) {
  if (sel) {
    for (int j = 0; j < n; j++) { int i = sel[j]; res[i] = col1[i] + col2[i]; }
  } else {
    for (int i = 0; i < n; i++) res[i] = col1[i] + col2[i];
  }
}

int select_lt(int n, int *res, const date *col, date val) {
  int k = 0;
  for (int i = 0; i < n; i++) {
    res[k] = i;            // always write
    k += (col[i] < val);   // advance only on match
  }
  return k;
}
